    // CONFIG
    // ------------------------------------------------------------

    const config = {
        sheetId:
            '1C64FsfoxaKCvtEVciCeZi3yTnqryDbvtB3EdSzqNWqM',

        sheetName:
            'FAQs',

        apiKey:
            'AIzaSyDbiZYZBlzvpHdDUWtVs76H3akcKuD-qQE',

        selector:
            '#tdr-faq',

        // false = opening one answer closes the others.
        allowMultiple:
            false,
    };


    // ------------------------------------------------------------
    // HELPERS
    // ------------------------------------------------------------

    const esc = value => {
        return String(value ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    };


    const normalizeUrl = value => {

        const url =
            String(value || '').trim();

        if (!url) {
            return '';
        }

        try {

            const parsed =
                new URL(url);

            if (
                parsed.protocol !== 'http:' &&
                parsed.protocol !== 'https:' &&
                parsed.protocol !== 'mailto:' &&
                parsed.protocol !== 'tel:'
            ) {
                return '';
            }

            return parsed.href;

        } catch {
            return '';
        }
    };


